import SwiftUI

struct CustomBindingView: View {
    var body: some View {
        let binding = Binding<Int>(
            get: { 42 },
            set: { _ in }
        )
        return Text("\(binding.wrappedValue)")
    }
}

let view = CustomBindingView()
print(view.body is Text)

