import SwiftUI

struct ToggleButton: View {
    @Binding var isSelected: Bool
    var body: some View {
        Button("Toggle") {
            isSelected.toggle()
        }
    }
}

let btn = ToggleButton(isSelected: .constant(false))
print("ToggleButton created: \(type(of: btn))")

